/**
 * Loads and validates the training program from data/plan.json.
 *
 * The JSON is generated by scripts/gen-plan.ts; edit that, not the JSON.
 * Rest days are not stored: a date with no session for an athlete is a rest
 * day, and the matcher infers "rest" from the absence.
 */

import planJson from "../../../data/plan.json";
import type { AthleteSlug, PlanSession, Sport } from "./types";
import { addDays, daysBetween, isISODate, type ISODate, weekStartOf } from "./dates";

export const PLAN_START: ISODate = "2026-11-02";
export const RACE_DATE: ISODate = "2027-04-04";
export const PLAN_WEEKS = 22;

export interface PhaseSpec {
  name: string;
  /** Inclusive week range. */
  weeks: [number, number];
}

export const PHASES: readonly PhaseSpec[] = [
  { name: "Base 1", weeks: [1, 4] },
  { name: "Base 2", weeks: [5, 8] },
  { name: "Build 1", weeks: [9, 12] },
  { name: "Build 2", weeks: [13, 16] },
  { name: "Peak", weeks: [17, 19] },
  { name: "Taper", weeks: [20, 22] },
];

export interface PlanWeek {
  /** 1-based week of the program. Can be 0 or negative before the start and above 22 after the race. */
  week: number;
  /** Phase name, or null when the date falls outside the program. */
  phase: string | null;
  /** Monday, YYYY-MM-DD. */
  start: ISODate;
  /** Sunday, YYYY-MM-DD. */
  end: ISODate;
}

const SPORTS: readonly Sport[] = ["swim", "bike", "run", "strength", "other"];
const ATHLETES: readonly AthleteSlug[] = ["filippo", "amir"];

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function nullableNumber(v: unknown): v is number | null {
  return v === null || (typeof v === "number" && Number.isFinite(v));
}

/** Throws with a precise message when a session is malformed. */
export function validateSession(raw: unknown, index: number): PlanSession {
  const where = `plan[${index}]`;
  if (!isRecord(raw)) throw new Error(`${where}: not an object`);
  const { id, date, sport, title, detail, targetMin, targetKm, athletes, phase, week } = raw;
  if (typeof id !== "string" || id.length === 0) throw new Error(`${where}: id must be a non-empty string`);
  if (!isISODate(date)) throw new Error(`${where} (${id}): date must be YYYY-MM-DD`);
  if (typeof sport !== "string" || !SPORTS.includes(sport as Sport)) throw new Error(`${where} (${id}): unknown sport ${String(sport)}`);
  if (typeof title !== "string" || title.length === 0) throw new Error(`${where} (${id}): title required`);
  if (detail !== null && typeof detail !== "string") throw new Error(`${where} (${id}): detail must be string or null`);
  if (!nullableNumber(targetMin)) throw new Error(`${where} (${id}): targetMin must be number or null`);
  if (!nullableNumber(targetKm)) throw new Error(`${where} (${id}): targetKm must be number or null`);
  if (!Array.isArray(athletes) || !athletes.every((a) => ATHLETES.includes(a as AthleteSlug)))
    throw new Error(`${where} (${id}): athletes must be a list of known slugs`);
  if (phase !== null && typeof phase !== "string") throw new Error(`${where} (${id}): phase must be string or null`);
  if (typeof week !== "number" || !Number.isInteger(week) || week < 1) throw new Error(`${where} (${id}): week must be a positive integer`);
  return {
    id,
    date,
    sport: sport as Sport,
    title,
    detail,
    targetMin,
    targetKm,
    athletes: athletes as AthleteSlug[],
    phase,
    week,
  };
}

export function validatePlan(raw: unknown): PlanSession[] {
  if (!Array.isArray(raw)) throw new Error("plan must be an array");
  const seen = new Set<string>();
  const sessions = raw.map((r, i) => validateSession(r, i));
  for (const s of sessions) {
    if (seen.has(s.id)) throw new Error(`plan: duplicate id ${s.id}`);
    seen.add(s.id);
  }
  return sessions.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.id < b.id ? -1 : 1));
}

let cached: PlanSession[] | null = null;

/** The full program, validated once and sorted by date. */
export function getPlan(): PlanSession[] {
  if (!cached) cached = validatePlan(planJson);
  return cached;
}

/** Whether a session applies to the athlete (empty list means everyone). */
export function appliesTo(session: PlanSession, athlete: AthleteSlug): boolean {
  return session.athletes.length === 0 || session.athletes.includes(athlete);
}

/** Sessions prescribed for one athlete on one day. Empty means rest. */
export function sessionsOn(date: ISODate, athlete: AthleteSlug, plan: PlanSession[] = getPlan()): PlanSession[] {
  return plan.filter((s) => s.date === date && appliesTo(s, athlete));
}

/** Sessions for one athlete in an inclusive date range. */
export function sessionsBetween(from: ISODate, to: ISODate, athlete: AthleteSlug, plan: PlanSession[] = getPlan()): PlanSession[] {
  return plan.filter((s) => s.date >= from && s.date <= to && appliesTo(s, athlete));
}

export function phaseForWeek(week: number): string | null {
  const p = PHASES.find((ph) => week >= ph.weeks[0] && week <= ph.weeks[1]);
  return p ? p.name : null;
}

/** Which program week a date falls in. Week 1 starts on PLAN_START (a Monday). */
export function weekOf(date: ISODate): PlanWeek {
  const start = weekStartOf(date);
  const week = Math.floor(daysBetween(PLAN_START, start) / 7) + 1;
  return { week, phase: phaseForWeek(week), start, end: addDays(start, 6) };
}

/** Monday of a given program week. */
export function weekStart(week: number): ISODate {
  return addDays(PLAN_START, (week - 1) * 7);
}

/** First and last calendar dates covered by the program. */
export function planWindow(): { from: ISODate; to: ISODate; weeks: number } {
  return { from: PLAN_START, to: addDays(PLAN_START, PLAN_WEEKS * 7 - 1), weeks: PLAN_WEEKS };
}

/** Whole days until race day from `today`; negative after the race. */
export function daysToRace(today: ISODate): number {
  return daysBetween(today, RACE_DATE);
}
